INSERT IGNORE INTO content_piece
  (id, section, note_type, priority, trigger_expr, heading, body, active)
VALUES
  ('LADDER-INTRO', 'LADDER', NULL, 100, 'ALWAYS', NULL, 'This is not a ranking against other brands. It is the standard every business is measured against, and it shows what a brand at each level typically looks like.', TRUE),
  ('LADDER-5', 'LADDER', NULL, 50, 'ALWAYS', NULL, 'Proven numbers, documented systems and the ability to support partners. The main risk is growing faster than support can follow.', TRUE),
  ('LADDER-4', 'LADDER', NULL, 40, 'ALWAYS', NULL, 'Strong foundations. The questions now are model, fee, territory and partner selection — not whether to franchise.', TRUE),
  ('LADDER-3', 'LADDER', NULL, 30, 'ALWAYS', NULL, 'Franchisable, but with conditions to settle before partners join. Skipping them is usually paid for by the first franchise owner.', TRUE),
  ('LADDER-2', 'LADDER', NULL, 20, 'ALWAYS', NULL, 'A working business with real customers. What is missing is the documentation, systems or support capacity someone else would need.', TRUE),
  ('LADDER-1', 'LADDER', NULL, 10, 'ALWAYS', NULL, 'The business works, but it depends on the founder and is not yet written down. Franchising now would put a partner at risk.', TRUE),
  ('LADDER-CLOSE-SPAN', 'LADDER', NULL, 5, 'band_count >= 2', NULL, 'Your score range of {low} to {high} covers these two levels.', TRUE),
  ('LADDER-CLOSE-ONE', 'LADDER', NULL, 5, 'band_count == 1', NULL, 'Your score range of {low} to {high} sits inside a single level.', TRUE),
  ('UPGRADE-HEADING', 'UPGRADE', NULL, 100, 'ALWAYS', NULL, 'If You Want to Know Exactly Where You Stand', TRUE),
  ('UPGRADE-TIER2', 'UPGRADE', NULL, 90, 'ALWAYS', 'The Franchise Readiness Report', 'About thirty more questions, roughly 15 minutes. Your earlier answers carry over — no question is asked twice.\n\n- **Your exact score** — one number, not a range\n- **All 7 areas explained in writing** — what is working, what is not, and why it matters for franchising\n- **Your problems ranked** — so you know which area to work on first\n- **Your full legal and approvals check**\n- **Where you stand** compared with similar brands we have worked with\n\n**₹1,999 + 18% GST** · ₹2,359 payable\n\nYou will receive your report within 24 hours.', TRUE),
  ('IP-UE01-5', 'IMPORTANT_POINTS', 'ok', 85, 'UE01 == 5', NULL, 'Your outlet pays back in under 12 months. That is the first number a franchise investor looks at, and yours is strong.', TRUE),
  ('IP-UE01-4', 'IMPORTANT_POINTS', 'ok', 70, 'UE01 == 4', NULL, 'Your outlet earns back its cost in 12 to 18 months. That is a workable base to build a franchise offer on.', TRUE),
  ('IP-UE01-3', 'IMPORTANT_POINTS', 'warn', 75, 'UE01 == 3', NULL, 'An 18 to 24 month payback sits at the longer end of what investors compare against.', TRUE),
  ('IP-UE01-2', 'IMPORTANT_POINTS', 'warn', 88, 'UE01 == 2', NULL, 'A 24 to 36 month payback is longer than most franchise investors accept without a strong reason.', TRUE),
  ('IP-UE01-1', 'IMPORTANT_POINTS', 'warn', 95, 'UE01 == 1', NULL, 'A payback beyond 36 months is very hard to put in front of an investor, whatever the rest of the business looks like.', TRUE),
  ('IP-UE02-5', 'IMPORTANT_POINTS', 'ok', 80, 'UE02 == 5', NULL, 'An outlet margin above 25% leaves comfortable room for both you and a franchise owner to earn.', TRUE),
  ('IP-UE02-4', 'IMPORTANT_POINTS', 'ok', 70, 'UE02 == 4', NULL, 'A 20 to 25% outlet margin leaves room for a fee and a royalty without squeezing the owner.', TRUE),
  ('IP-UE02-3', 'IMPORTANT_POINTS', 'ok', 60, 'UE02 == 3', NULL, 'A 15 to 20% outlet margin is workable. The full report checks whether it stays workable once a franchise owner pays a fee and a royalty on top.', TRUE),
  ('IP-UE02-2', 'IMPORTANT_POINTS', 'warn', 85, 'UE02 == 2', NULL, 'A 10 to 15% margin is thin once a royalty comes out of it. This is the number most likely to set your ceiling.', TRUE),
  ('IP-UE02-1', 'IMPORTANT_POINTS', 'warn', 95, 'UE02 == 1', NULL, 'Below 10%, there is not enough margin for a franchise owner to earn after paying you.', TRUE),
  ('IP-OR01-5', 'IMPORTANT_POINTS', 'ok', 90, 'OR01 == 5', NULL, 'Your operating procedures are written down. This is the single most useful thing you can have built at this stage.', TRUE),
  ('IP-OR01-3', 'IMPORTANT_POINTS', 'mile', 72, 'OR01 == 3', NULL, 'Your procedures are partly written down. Finishing them is mostly recording what you and your team already do.', TRUE),
  ('IP-OR01-1', 'IMPORTANT_POINTS', 'warn', 92, 'OR01 == 1', NULL, 'Your procedures are not written down. A franchise owner in another city cannot learn by working alongside you.', TRUE),
  ('IP-OR02-5', 'IMPORTANT_POINTS', 'ok', 82, 'OR02 == 5', NULL, 'Every core workflow has an SOP a new manager could follow. Few businesses at your stage can say that.', TRUE),
  ('IP-OR02-4', 'IMPORTANT_POINTS', 'ok', 74, 'OR02 == 4', NULL, 'Most core workflows have an SOP a new manager could follow unassisted.', TRUE),
  ('IP-OR02-3', 'IMPORTANT_POINTS', 'mile', 68, 'OR02 == 3', NULL, 'About half your workflows have an SOP. The half that does not is usually the half that needs judgement.', TRUE),
  ('IP-OR02-2', 'IMPORTANT_POINTS', 'warn', 84, 'OR02 == 2', NULL, 'Only a few workflows have a written SOP. Most of how this business runs still lives with people rather than on paper.', TRUE),
  ('IP-OR02-1', 'IMPORTANT_POINTS', 'warn', 90, 'OR02 == 1', NULL, 'No workflow has a written SOP yet. Everything a franchise owner would need to know is currently held by your team.', TRUE),
  ('IP-BP01-5', 'IMPORTANT_POINTS', 'ok', 78, 'BP01 == 5', NULL, 'More than 40 franchise enquiries last year. Demand for the franchise itself is already proven.', TRUE),
  ('IP-BP01-4', 'IMPORTANT_POINTS', 'ok', 70, 'BP01 == 4', NULL, '16 to 40 franchise enquiries last year. There is real inbound interest to work with.', TRUE),
  ('IP-BP01-3', 'IMPORTANT_POINTS', 'ok', 58, 'BP01 == 3', NULL, '6 to 15 franchise enquiries last year. There is genuine interest, and it is still early.', TRUE),
  ('IP-BP01-2', 'IMPORTANT_POINTS', 'warn', 55, 'BP01 == 2', NULL, '1 to 5 franchise enquiries last year. Demand for the franchise itself is still early, even where demand from customers clearly is not.', TRUE),
  ('IP-BP01-1', 'IMPORTANT_POINTS', 'warn', 62, 'BP01 == 1', NULL, 'No franchise enquiries last year. Nothing is pulling investors toward you yet, so partners will have to be found rather than answered.', TRUE),
  ('IP-MR01-5', 'IMPORTANT_POINTS', 'ok', 86, 'MR01 == 5', NULL, 'The model has worked in four or more cities. That removes the biggest question a franchise investor has.', TRUE),
  ('IP-MR01-3', 'IMPORTANT_POINTS', 'ok', 72, 'MR01 == 3', NULL, 'The model has worked in two or three cities. It has already travelled beyond its home ground.', TRUE),
  ('IP-MR01-1', 'IMPORTANT_POINTS', 'mile', 76, 'MR01 == 1', NULL, 'The model is proven in one city. Showing it works in a second is the step that changes the conversation with every investor.', TRUE),
  ('IP-PP01-5', 'IMPORTANT_POINTS', 'ok', 66, 'PP01 == 5', NULL, 'You already know what kind of partner you are looking for. Many brands reach their first franchise conversation without this.', TRUE),
  ('IP-PP01-3', 'IMPORTANT_POINTS', 'mile', 60, 'PP01 == 3', NULL, 'You have a rough idea of the right partner. Writing it down is what makes it usable when someone persuasive calls.', TRUE),
  ('IP-PP01-1', 'IMPORTANT_POINTS', 'warn', 80, 'PP01 == 1', NULL, 'You have not defined who the right partner is. Partner choice is the one franchise decision that cannot be undone afterwards.', TRUE),
  ('IP-SI01-5', 'IMPORTANT_POINTS', 'ok', 76, 'SI01 == 5', NULL, 'A structured training programme already exists. A franchise owner leans on training hardest in their first 90 days.', TRUE),
  ('IP-SI01-3', 'IMPORTANT_POINTS', 'mile', 70, 'SI01 == 3', NULL, 'Your training programme is partly built. Completing it is mostly writing down what you and your team already do.', TRUE),
  ('IP-SI01-1', 'IMPORTANT_POINTS', 'warn', 86, 'SI01 == 1', NULL, 'There is no training programme yet. This is what a franchise fee is nominally paid for, and the first question a serious investor asks.', TRUE),
  ('IP-FL01-5', 'IMPORTANT_POINTS', 'ok', 84, 'FL01 == 5', NULL, 'The business operates without you in daily decisions. That is the position from which a founder can genuinely support partners.', TRUE),
  ('IP-FL01-4', 'IMPORTANT_POINTS', 'ok', 74, 'FL01 == 4', NULL, 'Your managers make operational decisions independently and you review outcomes rather than approving in advance.', TRUE),
  ('IP-FL01-3', 'IMPORTANT_POINTS', 'ok', 64, 'FL01 == 3', NULL, 'A manager already runs the day to day within limits you set. You are not the bottleneck you could have been.', TRUE),
  ('IP-FL01-2', 'IMPORTANT_POINTS', 'warn', 82, 'FL01 == 2', NULL, 'Your team handles routine tasks, but decisions still come to you. Franchise support would land on top of that load.', TRUE),
  ('IP-FL01-1', 'IMPORTANT_POINTS', 'warn', 94, 'FL01 == 1', NULL, 'Most daily decisions still come to you. A franchise network multiplies demands on the person who is already the constraint.', TRUE),
  ('IP-OUTLETS-1', 'IMPORTANT_POINTS', 'mile', 78, 'outlets == \'1\'', NULL, 'A second outlet you run yourself is what proves the model repeats. It is the next step in the journey, not a gap in the business.', TRUE),
  ('WN-STRUCTURE-FIRST', 'WHAT_WE_NOTICED', NULL, 95, 'OR01 == 5 AND OR02 >= 4 AND outlets == \'1\'', 'You have built the structure before the scale.', 'Written procedures and SOPs for most of what you do, at one outlet. Most businesses do this the other way round: they grow first and document later, then spend a year fixing it. You are in the rarer, easier position.', TRUE),
  ('WN-SCALE-FIRST', 'WHAT_WE_NOTICED', NULL, 94, 'outlets IN (\'6–15\', \'16+\') AND OR01 != 5', 'You have grown faster than you have written things down.', '{outlets} outlets running on knowledge your team carries rather than on paper. That works while you can reach everyone. A franchise owner in another city cannot be reached the same way, and what is undocumented becomes their own invention.', TRUE),
  ('WN-SECOND-OUTLET', 'WHAT_WE_NOTICED', NULL, 90, 'outlets == \'1\'', 'Your next milestone is a second outlet you run yourself.', 'A franchise investor is buying proof that the model works more than once. A second location under your own management is the shortest way to show it.', TRUE),
  ('WN-NUMBERS-STRONG', 'WHAT_WE_NOTICED', NULL, 81, 'UE01 == 5 AND UE02 >= 4', 'Your numbers are the strongest part of your offer.', 'A payback under twelve months on a healthy margin is the combination investors look for first, and it is the part of this report you will not have to explain to anybody.', TRUE),
  ('WN-NUMBERS-STEADY', 'WHAT_WE_NOTICED', NULL, 80, 'UE01 == 4 AND UE02 IN (3, 4)', 'Your numbers are steady rather than stretched.', 'The payback and margin you reported make a workable base. The question the full report answers is whether they stay workable once a franchise owner pays a fee and a royalty on top.', TRUE),
  ('WN-MARGIN-CEILING', 'WHAT_WE_NOTICED', NULL, 88, 'UE02 <= 2', 'Your margin is what will set your ceiling.', 'Everything else can be fixed with work. A thin margin cannot, because a franchise owner has to earn a living from what is left after they pay you. This is the number to look at before anything else on this page.', TRUE),
  ('WN-PAYBACK-QUESTIONED', 'WHAT_WE_NOTICED', NULL, 86, 'UE01 <= 2 AND UE02 >= 3', 'Your margin works. Your payback is the part that will be questioned.', 'An investor comparing three opportunities compares payback first. A healthy margin does not rescue a long one — it just means the money comes back slowly rather than not at all.', TRUE),
  ('WN-WANTED-NOT-TRAVELLED', 'WHAT_WE_NOTICED', NULL, 84, 'BP01 >= 3 AND MR01 == 1', 'People want this. Nobody has yet shown it travels.', 'You have real customer demand and real enquiries. What has not been tested is whether the same thing works somewhere your name means nothing. That is the assumption a franchise owner is being asked to buy.', TRUE),
  ('WN-PULL-WITHOUT-READINESS', 'WHAT_WE_NOTICED', NULL, 92, 'BP01 >= 4 AND SI01 <= 3', 'Investors are already calling, and you are not yet set up to answer them.', 'Inbound interest is the hardest thing to manufacture and you have it. The risk now is the opposite of the usual one: signing a partner before there is anything to hand them.', TRUE),
  ('WN-FOUNDER-DEPENDENT', 'WHAT_WE_NOTICED', NULL, 93, 'FL01 <= 2', 'The business still runs through you.', 'This is often what makes a single outlet good, so it is not a criticism. But franchise support is a demand on your time that arrives on top of everything you already carry, and it arrives exactly when a new partner needs you most.', TRUE),
  ('WN-FOUNDER-FREE', 'WHAT_WE_NOTICED', NULL, 87, 'FL01 >= 4 AND outlets != \'1\'', 'You have already done the hardest part.', 'A business that runs without its founder across more than one location has cleared the thing most brands never clear. Whatever else this report says, that part is behind you.', TRUE),
  ('WN-LEGAL-EARLY', 'WHAT_WE_NOTICED', NULL, 60, 'G1 != \'Neither\' AND G3 == \'No\' AND outlets IN (\'1\', \'2–5\')', 'You protected the brand before you needed to.', 'A trademark filed at one or two outlets is unusual. Franchising means licensing your name to someone else, and you cannot license what you do not own.', TRUE),
  ('WN-NO-TRADEMARK', 'WHAT_WE_NOTICED', NULL, 96, 'G1 == \'Neither\'', 'One short piece of paperwork is holding your result down.', 'Your brand name is not yet trademarked or filed. This is not a structural problem with the business and it is not expensive to fix — but it caps your result, because you cannot license a name you do not own.', TRUE),
  ('WN-NOTHING-TO-SELL', 'WHAT_WE_NOTICED', NULL, 89, 'SI01 == 1 AND PP01 == 1', 'You have not yet decided what you would be selling.', 'No training programme and no defined partner profile. A franchise fee buys support and a place in a system, and at the moment neither has been described. That is a question to settle before a first conversation, not during one.', TRUE),
  ('WN-READY-TO-STRUCTURE', 'WHAT_WE_NOTICED', NULL, 82, 'band == \'READY_TO_PLAN\' OR band == \'READY_TO_SCALE\'', 'The question in front of you is no longer whether to franchise.', 'Your foundations hold. What decides the next twelve months is model, fee, territory and who you let in — and those are the decisions that are expensive to get wrong and cheap to get right.', TRUE),
  ('NS-BAND-5', 'IN_A_NUTSHELL', NULL, 100, 'band == \'READY_TO_SCALE\'', NULL, 'You are **as ready as brands get** before the first partner signs.', TRUE),
  ('NS-BAND-4', 'IN_A_NUTSHELL', NULL, 100, 'band == \'READY_TO_PLAN\'', NULL, 'Your foundations are **sound** — the open questions are about structure, not readiness.', TRUE),
  ('NS-BAND-3', 'IN_A_NUTSHELL', NULL, 100, 'band == \'ALMOST_READY\'', NULL, 'You are **close**, with specific conditions to settle before partners join.', TRUE),
  ('NS-BAND-2', 'IN_A_NUTSHELL', NULL, 100, 'band == \'EARLY_STAGE\'', NULL, 'You have **a working business** and the franchise scaffolding is not yet built.', TRUE),
  ('NS-BAND-1', 'IN_A_NUTSHELL', NULL, 100, 'band == \'NOT_YET_READY\'', NULL, 'Franchising now would be **early** — and several of the gaps are a year\'s work, not a decade\'s.', TRUE),
  ('NS-PROVEN-1CITY', 'IN_A_NUTSHELL', NULL, 90, 'MR01 == 1', NULL, 'The model is proven **with customers**. It is not yet proven **in a second location**.', TRUE),
  ('NS-PROVEN-MULTI', 'IN_A_NUTSHELL', NULL, 90, 'MR01 >= 3', NULL, 'The model has already worked **outside its home ground**, which is the question most brands cannot answer.', TRUE),
  ('NS-ASSET-SYSTEMS', 'IN_A_NUTSHELL', NULL, 80, 'OR >= 80', NULL, 'Your **written systems** are your strongest asset, and they make everything ahead of you easier.', TRUE),
  ('NS-ASSET-NUMBERS', 'IN_A_NUTSHELL', NULL, 80, 'UE >= 80', NULL, 'Your **unit economics** are the strongest part of the offer — the part investors test first.', TRUE),
  ('NS-ASSET-INDEPENDENCE', 'IN_A_NUTSHELL', NULL, 80, 'FL >= 80', NULL, 'The business **runs without you**, which is the part most founders never finish.', TRUE),
  ('NS-ASSET-PULL', 'IN_A_NUTSHELL', NULL, 78, 'BP >= 80', NULL, '**Investors are already asking**, which is the hardest thing on this page to manufacture.', TRUE),
  ('NS-GAP-TRAINING', 'IN_A_NUTSHELL', NULL, 70, 'SI01 <= 3', NULL, 'The **training programme** is the main piece still to finish.', TRUE),
  ('NS-GAP-SOPS', 'IN_A_NUTSHELL', NULL, 70, 'OR01 <= 3 OR OR02 <= 3', NULL, '**Writing down how the work is done** is the main piece still to finish.', TRUE),
  ('NS-GAP-MARGIN', 'IN_A_NUTSHELL', NULL, 74, 'UE02 <= 2', NULL, 'The **margin** is the constraint, and it limits what you can charge a partner.', TRUE),
  ('NS-GAP-PARTNER', 'IN_A_NUTSHELL', NULL, 68, 'PP01 == 1', NULL, '**Who the right partner is** has not yet been decided, and it is the one choice that cannot be undone.', TRUE),
  ('NS-NEXT-SECOND-OUTLET', 'IN_A_NUTSHELL', NULL, 60, 'outlets == \'1\'', NULL, 'Your next milestone is **repeating the outlet yourself** — a business decision, not a fix.', TRUE),
  ('NS-NEXT-STRUCTURE', 'IN_A_NUTSHELL', NULL, 60, 'outlets != \'1\' AND band IN (\'READY_TO_PLAN\', \'READY_TO_SCALE\')', NULL, 'Your next milestone is **deciding the offer**, not improving the business.', TRUE),
  ('CT-INTRO', 'CANNOT_TELL', NULL, 100, 'ALWAYS', NULL, 'This test asked you nine scoring questions. Your full score is decided by forty. Three things it cannot answer:', TRUE),
  ('CT-RANGE', 'CANNOT_TELL', NULL, 100, 'ALWAYS', 'Are you at {low}, or at {high}?', 'At {low} there is foundational work to finish first. At {high} you are close enough to start structuring the offer. That is a meaningful difference in what you do next year.', TRUE),
  ('CT-W-UE', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'UE\'', 'Do your numbers survive a franchise fee?', 'Two questions can see your payback and margin. They cannot model what is left for a partner after they pay you. Six can.', TRUE),
  ('CT-W-OR', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'OR\'', 'Are your written systems complete enough for an outsider?', 'You told us how much is documented. Two questions cannot test whether the undocumented part is the important part. Six can.', TRUE),
  ('CT-W-SI', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'SI\'', 'What would a partner actually receive for their fee?', 'One question asked whether training exists. It cannot describe what you would be committing to deliver, every month, for ten years.', TRUE),
  ('CT-W-FL', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'FL\'', 'How much of the business genuinely runs without you?', 'One question asked how you delegate. It cannot check that answer against what actually happened in the last ninety days.', TRUE),
  ('CT-W-MR', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'MR\'', 'Would this work where nobody knows your name?', 'One question counted your cities. It cannot tell you what makes a location work, which is what you would need to assess a partner\'s site.', TRUE),
  ('CT-W-BP', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'BP\'', 'Is your brand worth paying for?', 'One question counted enquiries. It cannot tell you whether an investor doing their own research would find enough to justify your fee.', TRUE),
  ('CT-W-PP', 'CANNOT_TELL', NULL, 90, 'weakest_pillar == \'PP\'', 'Would you recognise the wrong partner?', 'One question asked whether you have a profile. It cannot test whether you would apply it when a persuasive candidate with cash is sitting in front of you.', TRUE),
  ('CT-RANK-MANY', 'CANNOT_TELL', NULL, 80, 'weak_count >= 2', 'Which of your {weak_count} weaker areas to work on first?', 'They are not equal in what they cost you. Working on the wrong one first is how a year gets spent.', TRUE),
  ('CT-RANK-FEW', 'CANNOT_TELL', NULL, 80, 'weak_count <= 1', 'How deep does the one gap actually run?', 'A single weak area can be a month of work or a year of it. Nine questions cannot tell the difference, and the difference is your whole timeline.', TRUE),
  ('CDN-LEAD-DISPUTE', 'CAN_DO_NOW', NULL, 100, 'G3 == \'Yes\'', NULL, 'One thing has to be settled before anything else on this page matters.', TRUE),
  ('CDN-LEAD-TM', 'CAN_DO_NOW', NULL, 90, 'G1 == \'Neither\'', NULL, 'One thing on the paperwork side is holding your result down, and it is within your control this month.', TRUE),
  ('CDN-LEAD-CLEAN', 'CAN_DO_NOW', NULL, 80, 'G1 != \'Neither\' AND G3 == \'No\'', NULL, 'There is nothing on the legal or paperwork side holding you back. Your trademark is filed and there are no disputes.', TRUE),
  ('CDN-FILE-TM', 'CAN_DO_NOW', NULL, 100, 'G1 == \'Neither\'', 'File your trademark.', 'Franchising means licensing your brand to someone else, and you cannot license what you do not own. Filing is short and inexpensive, and your result stops being capped the day the application goes in.', TRUE),
  ('CDN-RESOLVE-DISPUTE', 'CAN_DO_NOW', NULL, 100, 'G3 == \'Yes\'', 'Resolve the dispute.', 'A franchise agreement grants rights the brand has to be able to defend. Until this is settled, every conversation you have is one you cannot close.', TRUE),
  ('CDN-FINISH-TRAINING', 'CAN_DO_NOW', NULL, 80, 'SI01 == 3', 'Finish the training programme.', 'You already train your own team. Writing that down as a programme someone outside your business could follow is the same work, done once.', TRUE),
  ('CDN-SECOND-OUTLET', 'CAN_DO_NOW', NULL, 70, 'outlets == \'1\'', 'Open or plan your second outlet.', 'This is the milestone that changes the conversation with every investor who calls you.', TRUE),
  ('CDN-FINISH-SOPS', 'CAN_DO_NOW', NULL, 75, 'OR01 == 3', 'Finish writing down your procedures.', 'The part that is already in your head is the part a franchise owner cannot reach. Recording it costs you nothing but time and makes everything ahead of you easier.', TRUE),
  ('CDN-FALLBACK', 'CAN_DO_NOW', NULL, 0, 'ALWAYS', NULL, 'There is nothing outstanding on the legal or paperwork side, and nothing we would ask you to fix before the next stage. You are ready to go further whenever you are.', TRUE);
